import{_ as a,H as s,f as n,i as t}from"./chunks/framework.BH2BK_3i.js";const g=JSON.parse('{"title":"18｜庖丁解牛：Tools 工具系统内核剖析","description":"","frontmatter":{},"headers":[{"level":2,"title":"Agentic Loop——工具驱动的智能循环","slug":"agentic-loop——工具驱动的智能循环","link":"#agentic-loop——工具驱动的智能循环","children":[]},{"level":2,"title":"Claude Code 内置工具完整清单","slug":"claude-code-内置工具完整清单","link":"#claude-code-内置工具完整清单","children":[]},{"level":2,"title":"工具的风险等级","slug":"工具的风险等级","link":"#工具的风险等级","children":[]},{"level":2,"title":"从原语到涌现——工具设计哲学","slug":"从原语到涌现——工具设计哲学","link":"#从原语到涌现——工具设计哲学","children":[{"level":3,"title":"软件工程的五个原子操作","slug":"软件工程的五个原子操作","link":"#软件工程的五个原子操作","children":[]},{"level":3,"title":"类比：为什么编程语言只需要几条指令","slug":"类比-为什么编程语言只需要几条指令","link":"#类比-为什么编程语言只需要几条指令","children":[]},{"level":3,"title":"涌现：为什么 1+1 远大于 2","slug":"涌现-为什么-1-1-远大于-2","link":"#涌现-为什么-1-1-远大于-2","children":[]},{"level":3,"title":"“高级工具”是涌现出来的，不是内置的","slug":"高级工具-是涌现出来的-不是内置的","link":"#高级工具-是涌现出来的-不是内置的","children":[]},{"level":3,"title":"Bash：图灵完备的万能逃逸舱","slug":"bash-图灵完备的万能逃逸舱","link":"#bash-图灵完备的万能逃逸舱","children":[]}]},{"level":2,"title":"权限控制体系","slug":"权限控制体系","link":"#权限控制体系","children":[{"level":3,"title":"权限分层","slug":"权限分层","link":"#权限分层","children":[]},{"level":3,"title":"权限模式","slug":"权限模式","link":"#权限模式","children":[]},{"level":3,"title":"权限规则语法","slug":"权限规则语法","link":"#权限规则语法","children":[]},{"level":3,"title":"配置文件层级","slug":"配置文件层级","link":"#配置文件层级","children":[]},{"level":3,"title":"CLI 工具控制","slug":"cli-工具控制","link":"#cli-工具控制","children":[]}]},{"level":2,"title":"工具扩展与架构定位","slug":"工具扩展与架构定位","link":"#工具扩展与架构定位","children":[{"level":3,"title":"工具能力的三个层次","slug":"工具能力的三个层次","link":"#工具能力的三个层次","children":[]},{"level":3,"title":"工具是基础，其他机制是上层建筑","slug":"工具是基础-其他机制是上层建筑","link":"#工具是基础-其他机制是上层建筑","children":[]}]},{"level":2,"title":"总结一下","slug":"总结一下","link":"#总结一下","children":[]},{"level":2,"title":"思考题","slug":"思考题","link":"#思考题","children":[]},{"level":2,"title":"下一讲预告","slug":"下一讲预告","link":"#下一讲预告","children":[]}],"relativePath":"ClaudeCode工程化实战/18｜庖丁解牛：Tools工具系统内核剖析.md","filePath":"ClaudeCode工程化实战/18｜庖丁解牛：Tools工具系统内核剖析.md","lastUpdated":1779815462000}'),i={name:"ClaudeCode工程化实战/18｜庖丁解牛：Tools工具系统内核剖析.md"};function p(l,e,o,c,r,d){return s(),n("div",null,[...e[0]||(e[0]=[t(`<h1 id="_18-庖丁解牛-tools-工具系统内核剖析" tabindex="-1">18｜庖丁解牛：Tools 工具系统内核剖析 <a class="header-anchor" href="#_18-庖丁解牛-tools-工具系统内核剖析" aria-label="Permalink to &quot;18｜庖丁解牛：Tools 工具系统内核剖析&quot;">​</a></h1><blockquote><p>释题：庖丁解牛。庖丁之所以神，不是刀快，而是他知道牛的结构——骨节之间、筋络之处，刀刃游走其间，从无阻碍。理解 Claude Code 的工具系统也是一样：不需要记住每一个工具的参数，而是理解工具背后的设计哲学：五个原子操作、涌现的原理、权限的层次。理解了结构，用起来才能游刃有余。</p></blockquote><p>你好，我是黄佳。</p><p>上一讲我们学习了 MCP，通过开放协议将 Claude Code 连接到外部世界。GitHub、Notion、数据库……MCP 让 Claude 的能力边界从本地文件系统扩展到了整个数字世界。</p><p>但有一个更根本的问题我们一直没有深入讨论： <strong>Claude Code 内置的那些工具本身是怎么回事？</strong> Read、Write、Bash、Grep、Glob、Edit、Agent……这十几个“原生工具”是怎么组织的？为什么偏偏是这几个？它们和 MCP 扩展的外部工具又是什么关系？</p><p>这一讲，我们庖丁解牛，把 Claude Code 的工具系统彻底拆开来看。按照重要程度，这一讲本应放在基础篇，不过，因为目前大家知识体系已经很全面了，我还是决定放在这里，我们理解起来更深入。</p><h2 id="agentic-loop——工具驱动的智能循环" tabindex="-1">Agentic Loop——工具驱动的智能循环 <a class="header-anchor" href="#agentic-loop——工具驱动的智能循环" aria-label="Permalink to &quot;Agentic Loop——工具驱动的智能循环&quot;">​</a></h2><p>如果 Claude 没有工具，它只能做一件事： <strong>输出文本</strong>。</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>用户: 帮我修复 src/api.js 中的 bug</span></span>
<span class="line"><span>Claude:（思考）这应该是一个 JavaScript 文件...</span></span>
<span class="line"><span>       （继续思考）用户想让我修复 bug...</span></span>
<span class="line"><span>       （输出文本）&quot;您好，请提供 src/api.js 的内容，我来帮您分析问题。&quot;</span></span></code></pre></div><p>它能思考、能分析、能给建议，但 <strong>不能行动</strong>。</p><p>有了工具，情况完全不同，我们和Claude的交流可能是这样的。</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>用户: 帮我修复 src/api.js 中的 bug</span></span>
<span class="line"><span>Claude:（思考）让我先读取这个文件</span></span>
<span class="line"><span>       （调用 Read 工具）→ 获取文件内容</span></span>
<span class="line"><span>       （思考）我发现了问题，第 42 行的 null 检查缺失</span></span>
<span class="line"><span>       （调用 Edit 工具）→ 修改文件</span></span>
<span class="line"><span>       （思考）让我运行测试确认修复成功</span></span>
<span class="line"><span>       （调用 Bash 工具）→ 执行 npm test</span></span>
<span class="line"><span>       （输出）&quot;我已经修复了问题，测试全部通过。&quot;</span></span></code></pre></div><p><strong>工具让 Claude 从顾问变成了执行者。</strong></p><p>Claude Code 的工作循环——Agentic Loop 可以分为三个阶段，根据任务需要灵活切换。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E5%B7%A5%E7%A8%8B%E5%8C%96%E5%AE%9E%E6%88%98/images/957210/e89407a8ddef056f5bc509b6503cd81d.jpg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E5%B7%A5%E7%A8%8B%E5%8C%96%E5%AE%9E%E6%88%98/images/957210/e89407a8ddef056f5bc509b6503cd81d.jpg" alt=""></a><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E5%B7%A5%E7%A8%8B%E5%8C%96%E5%AE%9E%E6%88%98/images/957210/e63bf24c69fd64ea55507e3d8f6773a4.jpg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E5%B7%A5%E7%A8%8B%E5%8C%96%E5%AE%9E%E6%88%98/images/957210/e63bf24c69fd64ea55507e3d8f6773a4.jpg" alt=""></a></p><p>简单任务可能只需要一轮，复杂任务可能循环几十次。 <strong>每一次工具调用的返回结果，都会反馈给 Claude，影响下一步的决策。</strong></p><p>Claude（模型）负责 <strong>推理</strong>，Tools 负责 <strong>行动</strong>。而 Claude Code 扮演的角色是 <strong>Agentic Harness</strong>，它把模型和工具连接起来，提供执行环境、上下文管理、权限控制等基础设施。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E5%B7%A5%E7%A8%8B%E5%8C%96%E5%AE%9E%E6%88%98/images/957210/c56f8c4dc4ea0c47e6b9d9b6460fc8cb.jpg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E5%B7%A5%E7%A8%8B%E5%8C%96%E5%AE%9E%E6%88%98/images/957210/c56f8c4dc4ea0c47e6b9d9b6460fc8cb.jpg" alt=""></a></p><p>理解这个架构很重要，因为 <strong>你配置的所有扩展（Skills、Hooks、MCP）都是在这个 Harness 上工作的，而不是直接修改 Claude 模型本身。</strong></p><h2 id="claude-code-内置工具完整清单" tabindex="-1">Claude Code 内置工具完整清单 <a class="header-anchor" href="#claude-code-内置工具完整清单" aria-label="Permalink to &quot;Claude Code 内置工具完整清单&quot;">​</a></h2><p>早期，Claude Code 只是内置了十几个工具（目前逐渐增多，可能已经有20多个了，最新列表在 <a href="https://code.claude.com/docs/en/tools-reference" target="_blank" rel="noreferrer">这里</a>），按功能分为六个类别。</p><p><strong>文件操作类</strong>，Claude 与代码交互的最基本方式。Read 是只读的，不需要额外授权；Edit、Write、MultiEdit 会修改文件系统，因此需要用户确认。</p><p><strong>搜索类</strong>，Claude 的“眼睛”——在动手之前先看清楚代码库的全貌。Glob 按文件名模式定位文件，Grep 按内容搜索定位代码行，两者都是只读操作，无需授权。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E5%B7%A5%E7%A8%8B%E5%8C%96%E5%AE%9E%E6%88%98/images/957210/b67dfd847337200f70018e392c8a738d.jpg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E5%B7%A5%E7%A8%8B%E5%8C%96%E5%AE%9E%E6%88%98/images/957210/b67dfd847337200f70018e392c8a738d.jpg" alt=""></a></p><p><strong>执行类</strong>，整个工具集里能力最强也最危险的一个。Bash 可以执行操作系统能做的一切。正因如此，它始终需要用户授权。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E5%B7%A5%E7%A8%8B%E5%8C%96%E5%AE%9E%E6%88%98/images/957210/ca5e8cb9f2b72e382b266947590166ff.jpg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E5%B7%A5%E7%A8%8B%E5%8C%96%E5%AE%9E%E6%88%98/images/957210/ca5e8cb9f2b72e382b266947590166ff.jpg" alt=""></a></p><p><strong>网络类，</strong> 让 Claude 突破本地文件系统的边界，访问互联网上的信息。查文档、搜报错、获取 API 响应都靠这两个工具。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E5%B7%A5%E7%A8%8B%E5%8C%96%E5%AE%9E%E6%88%98/images/957210/f0b8fa3a9b6f4a08d62756bb98634f16.jpg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E5%B7%A5%E7%A8%8B%E5%8C%96%E5%AE%9E%E6%88%98/images/957210/f0b8fa3a9b6f4a08d62756bb98634f16.jpg" alt=""></a></p><p><strong>编排类</strong>，这组工具不直接操作代码，而是管理 Agent 的工作流程：把复杂任务委派给子代理、在需要时向用户提问、用任务清单跟踪多步骤进度。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E5%B7%A5%E7%A8%8B%E5%8C%96%E5%AE%9E%E6%88%98/images/957210/1b6d1f55a11b591783638c57d992f701.jpg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E5%B7%A5%E7%A8%8B%E5%8C%96%E5%AE%9E%E6%88%98/images/957210/1b6d1f55a11b591783638c57d992f701.jpg" alt=""></a></p><p><strong>辅助类</strong>，支撑性工具，用于管理后台任务和系统状态切换。日常使用中不常直接接触，但在自动化场景下不可或缺。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E5%B7%A5%E7%A8%8B%E5%8C%96%E5%AE%9E%E6%88%98/images/957210/43214f8f1cf7ceac3bf63ee185a6ebd3.jpg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E5%B7%A5%E7%A8%8B%E5%8C%96%E5%AE%9E%E6%88%98/images/957210/43214f8f1cf7ceac3bf63ee185a6ebd3.jpg" alt=""></a></p><h2 id="工具的风险等级" tabindex="-1">工具的风险等级 <a class="header-anchor" href="#工具的风险等级" aria-label="Permalink to &quot;工具的风险等级&quot;">​</a></h2><p>为什么要这样分类？因为不同类别的工具有不同的 <strong>风险等级</strong>：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E5%B7%A5%E7%A8%8B%E5%8C%96%E5%AE%9E%E6%88%98/images/957210/5a78db0bb5b8e1f80cbc1a481896554c.jpg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E5%B7%A5%E7%A8%8B%E5%8C%96%E5%AE%9E%E6%88%98/images/957210/5a78db0bb5b8e1f80cbc1a481896554c.jpg" alt=""></a></p><p>理解这个分类，你就能：</p><ul><li><p>为子代理配置 <strong>最小权限</strong>（只读任务只给 Read/Grep/Glob）</p></li><li><p>设计 <strong>防护机制</strong>（高风险工具加 Hook 检查）</p></li><li><p>理解 <strong>权限提示的逻辑</strong>（低风险工具不弹窗，高风险工具要确认）</p></li></ul><h2 id="从原语到涌现——工具设计哲学" tabindex="-1">从原语到涌现——工具设计哲学 <a class="header-anchor" href="#从原语到涌现——工具设计哲学" aria-label="Permalink to &quot;从原语到涌现——工具设计哲学&quot;">​</a></h2><p>看完工具清单，你可能会问：只有十几个内置工具，凭什么覆盖几乎所有软件工程任务？为什么没有看到重构工具、调试工具、部署工具这些高级工具？</p><p>答案指向同一个工程哲学： <strong>Claude Code 的工具集是一组精心选择的原语（primitives），而不是一组特化的高级能力。</strong></p><h3 id="软件工程的五个原子操作" tabindex="-1">软件工程的五个原子操作 <a class="header-anchor" href="#软件工程的五个原子操作" aria-label="Permalink to &quot;软件工程的五个原子操作&quot;">​</a></h3><p>一个开发者每天做的所有事情，无论多么复杂，都可以分解为五种原子操作。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E5%B7%A5%E7%A8%8B%E5%8C%96%E5%AE%9E%E6%88%98/images/957210/9439dd702e8e3c2015d6c1827801968e.jpg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E5%B7%A5%E7%A8%8B%E5%8C%96%E5%AE%9E%E6%88%98/images/957210/9439dd702e8e3c2015d6c1827801968e.jpg" alt=""></a></p><p>想想你的一天都会哪些动作？</p><ul><li><p>你打开文件看代码 → <strong>感知</strong></p></li><li><p>你搜索某个函数在哪里被调用 → <strong>搜索</strong></p></li><li><p>你修改代码修复一个 bug → <strong>修改</strong></p></li><li><p>你运行 <code>npm test</code> 验证修复 → <strong>执行</strong></p></li><li><p>你上 Stack Overflow 查错误信息 → <strong>获取</strong></p></li></ul><p>任何复杂任务，无论是“重构整个模块”还是“搭建 CI/CD 流水线”，都是这五种操作的不同排列组合。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E5%B7%A5%E7%A8%8B%E5%8C%96%E5%AE%9E%E6%88%98/images/957210/615760bd0bc450196db30116ed8ce3f8.jpg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E5%B7%A5%E7%A8%8B%E5%8C%96%E5%AE%9E%E6%88%98/images/957210/615760bd0bc450196db30116ed8ce3f8.jpg" alt=""></a></p><p><strong>这就是 Claude Code 工具设计的核心洞察：不需要为每种任务造一个专用工具，只需要把原子操作做好。</strong></p><h3 id="类比-为什么编程语言只需要几条指令" tabindex="-1">类比：为什么编程语言只需要几条指令 <a class="header-anchor" href="#类比-为什么编程语言只需要几条指令" aria-label="Permalink to &quot;类比：为什么编程语言只需要几条指令&quot;">​</a></h3><p>这个设计哲学并不新鲜，我们回顾一些优秀的产品，就能发现它们的思路都是这样。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E5%B7%A5%E7%A8%8B%E5%8C%96%E5%AE%9E%E6%88%98/images/957210/a257e66024b21752a3bd65af74248756.jpg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E5%B7%A5%E7%A8%8B%E5%8C%96%E5%AE%9E%E6%88%98/images/957210/a257e66024b21752a3bd65af74248756.jpg" alt=""></a></p><p>Unix 的设计哲学是“做好一件事”（Do One Thing Well），然后通过管道组合。Claude Code 的工具设计完全继承了这个思想，但比 Unix 管道强大得多。Unix 管道是预定义的、线性的。而 Claude Code 的组合是 <strong>动态的、分支的、自适应的</strong>，Claude 在每次工具调用后，根据返回的结果 <strong>重新推理</strong> 下一步该做什么。</p><h3 id="涌现-为什么-1-1-远大于-2" tabindex="-1">涌现：为什么 1+1 远大于 2 <a class="header-anchor" href="#涌现-为什么-1-1-远大于-2" aria-label="Permalink to &quot;涌现：为什么 1+1 远大于 2&quot;">​</a></h3><p><strong>为什么这些简单工具组合在一起，能产生远超其各自能力之和的效果？</strong></p><p>答案是 <strong>涌现</strong>（Emergence）：</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>涌现能力 = 原语工具 × LLM 推理 × 反馈循环</span></span></code></pre></div><ul><li><p><strong>原语工具</strong> 提供行动能力（感知、搜索、修改、执行、获取）</p></li><li><p><strong>LLM 推理</strong> 提供决策能力（理解任务 → 分解步骤 → 选择工具 → 解读结果）</p></li><li><p><strong>反馈循环</strong> 让二者持续交互（工具输出 → 新的理解 → 新的行动）</p></li></ul><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E5%B7%A5%E7%A8%8B%E5%8C%96%E5%AE%9E%E6%88%98/images/957210/9969f8f6e67a56b929b144acaa855073.jpg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E5%B7%A5%E7%A8%8B%E5%8C%96%E5%AE%9E%E6%88%98/images/957210/9969f8f6e67a56b929b144acaa855073.jpg" alt=""></a></p><p>我们用一个具体例子说明。比方说，我们要完成“修复用户登录时偶尔出现的 500 错误”这任务，虽然没有任何一个工具能“修复 bug”，但看看它们是怎么组合的。</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>第 1 步：Grep(&quot;500&quot;, &quot;error&quot;, &quot;login&quot;)</span></span>
<span class="line"><span>         → 找到 3 个文件中有相关错误日志</span></span>
<span class="line"><span>         → Claude 推理：&quot;日志显示错误出现在 auth-service.js&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>第 2 步：Read(&quot;src/auth-service.js&quot;)</span></span>
<span class="line"><span>         → 读取 200 行代码</span></span>
<span class="line"><span>         → Claude 推理：&quot;第 87 行的 token 验证没有 null 检查&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>第 3 步：Grep(&quot;validateToken&quot;, type: &quot;files_with_matches&quot;)</span></span>
<span class="line"><span>         → 找到 5 个文件引用了这个函数</span></span>
<span class="line"><span>         → Claude 推理：&quot;需要同时检查调用方是否有防御性处理&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>第 4 步：Read(&quot;src/middleware/auth.js&quot;)</span></span>
<span class="line"><span>         → 读取调用方代码</span></span>
<span class="line"><span>         → Claude 推理：&quot;调用方也没有 null 检查，需要在源头修复&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>第 5 步：Edit(&quot;src/auth-service.js&quot;, line 87)</span></span>
<span class="line"><span>         → 添加 null 检查</span></span>
<span class="line"><span></span></span>
<span class="line"><span>第 6 步：Bash(&quot;npm test -- --grep &#39;auth&#39;&quot;)</span></span>
<span class="line"><span>         → 运行测试，2 个失败</span></span>
<span class="line"><span>         → Claude 推理：&quot;测试用例需要更新&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>第 7 步：Edit(&quot;tests/auth.test.js&quot;)</span></span>
<span class="line"><span>         → 更新测试用例</span></span>
<span class="line"><span></span></span>
<span class="line"><span>第 8 步：Bash(&quot;npm test&quot;)</span></span>
<span class="line"><span>         → 全部通过</span></span></code></pre></div><p>单独看每一步，只是读文件、搜索文本、编辑文件、执行命令——极其简单。但组合起来看，Claude 完成了一次完整的 bug 调查、定位、修复、验证，还处理了跨文件依赖和测试更新。</p><p>这就是涌现—— <strong>复杂的智能行为从简单工具的交互中自然产生</strong>。</p><h3 id="高级工具-是涌现出来的-不是内置的" tabindex="-1">“高级工具”是涌现出来的，不是内置的 <a class="header-anchor" href="#高级工具-是涌现出来的-不是内置的" aria-label="Permalink to &quot;“高级工具”是涌现出来的，不是内置的&quot;">​</a></h3><p>这是一个非常重要的观点，首先我们拆解一下所谓的“高级能力”，实际是哪些工具的组合。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E5%B7%A5%E7%A8%8B%E5%8C%96%E5%AE%9E%E6%88%98/images/957210/ef765be28efc707effb559403e51a44c.jpg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E5%B7%A5%E7%A8%8B%E5%8C%96%E5%AE%9E%E6%88%98/images/957210/ef765be28efc707effb559403e51a44c.jpg" alt=""></a></p><p><strong>给 Claude 一个“重构工具”反而是有害的。</strong> 因为“重构”不是原子操作，它是一系列决策的集合。把决策权交给 Claude 的推理能力，比交给一个固定逻辑的工具更灵活。</p><h3 id="bash-图灵完备的万能逃逸舱" tabindex="-1">Bash：图灵完备的万能逃逸舱 <a class="header-anchor" href="#bash-图灵完备的万能逃逸舱" aria-label="Permalink to &quot;Bash：图灵完备的万能逃逸舱&quot;">​</a></h3><p>在所有工具中， <strong>Bash 最特殊</strong>。它是唯一一个“不确定做什么”的工具——其他工具都有明确职责，但 Bash 能做操作系统能做的一切。</p><p>从理论上说，仅凭 Bash 一个工具，Claude 就能完成所有任务：用 <code>cat</code> 读文件、 <code>sed</code> 改文件、 <code>find</code> 搜索。那为什么还需要 Read、Edit、Glob、Grep？</p><p>我认为有 <strong>三个原因</strong>。</p><ol><li><p><strong>结构化交互</strong>：Read 返回的文件内容带行号、受长度控制；Bash <code>cat</code> 返回原始文本。结构化返回值让 Claude 更准确地理解和定位代码。</p></li><li><p><strong>权限精细控制</strong>：你可以允许 Read 但禁止 Bash，这样 Claude 能看代码但不能执行任意命令。如果只有 Bash，权限就是全有或全无。</p></li><li><p><strong>Token 效率</strong>：Bash 输出通常包含大量冗余信息。专用工具返回精简的、Claude 直接需要的信息。</p></li></ol><p><strong>背后的设计原则是，Bash 提供能力的完备性</strong>，专用工具提供 <strong>交互的效率和安全的可控性</strong>。二者缺一不可。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E5%B7%A5%E7%A8%8B%E5%8C%96%E5%AE%9E%E6%88%98/images/957210/d481c3069d2beyyae78804f037936de3.jpg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E5%B7%A5%E7%A8%8B%E5%8C%96%E5%AE%9E%E6%88%98/images/957210/d481c3069d2beyyae78804f037936de3.jpg" alt=""></a></p><h2 id="权限控制体系" tabindex="-1">权限控制体系 <a class="header-anchor" href="#权限控制体系" aria-label="Permalink to &quot;权限控制体系&quot;">​</a></h2><p>如果说工具定义了“Claude 能做什么”，那么权限系统决定了“Claude 可以做到什么程度”。 同一组原语工具，在不同权限边界下，其行为能力和风险等级会呈现出完全不同的形态，这也是 Agent 系统从“可用”走向“可控”的关键一环。</p><p>从工程角度看，Claude Code 并不是简单地“给或不给权限”，而是构建了一套分层的权限控制体系：既保证低风险操作的流畅执行，又对高风险行为进行精细约束，从而在效率与安全之间取得平衡。</p><h3 id="权限分层" tabindex="-1">权限分层 <a class="header-anchor" href="#权限分层" aria-label="Permalink to &quot;权限分层&quot;">​</a></h3><p>Claude Code 使用分层权限系统来平衡能力和安全。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E5%B7%A5%E7%A8%8B%E5%8C%96%E5%AE%9E%E6%88%98/images/957210/56b1c786ab56669896ba951ebc9110b5.jpg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E5%B7%A5%E7%A8%8B%E5%8C%96%E5%AE%9E%E6%88%98/images/957210/56b1c786ab56669896ba951ebc9110b5.jpg" alt=""></a></p><p><strong>关键区别</strong> 是，Bash 命令点“Yes, don’t ask again”后 <strong>永久生效</strong>（该项目目录下），文件编辑的授权 <strong>只在当前会话有效</strong>。</p><h3 id="权限模式" tabindex="-1">权限模式 <a class="header-anchor" href="#权限模式" aria-label="Permalink to &quot;权限模式&quot;">​</a></h3><p>Claude Code 支持多种权限模式，通过 <code>Shift+Tab</code> 循环切换。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E5%B7%A5%E7%A8%8B%E5%8C%96%E5%AE%9E%E6%88%98/images/957210/4e155770b822538439a210ca16352983.jpg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E5%B7%A5%E7%A8%8B%E5%8C%96%E5%AE%9E%E6%88%98/images/957210/4e155770b822538439a210ca16352983.jpg" alt=""></a></p><h3 id="权限规则语法" tabindex="-1">权限规则语法 <a class="header-anchor" href="#权限规则语法" aria-label="Permalink to &quot;权限规则语法&quot;">​</a></h3><p>在 <code>settings.json</code> 中可以精细配置工具权限：</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>{</span></span>
<span class="line"><span>  &quot;permissions&quot;: {</span></span>
<span class="line"><span>    &quot;allow&quot;: [</span></span>
<span class="line"><span>      &quot;Bash(npm run *)&quot;,</span></span>
<span class="line"><span>      &quot;Bash(git status)&quot;,</span></span>
<span class="line"><span>      &quot;Bash(git diff *)&quot;,</span></span>
<span class="line"><span>      &quot;Read&quot;</span></span>
<span class="line"><span>    ],</span></span>
<span class="line"><span>    &quot;deny&quot;: [</span></span>
<span class="line"><span>      &quot;Bash(rm -rf *)&quot;,</span></span>
<span class="line"><span>      &quot;Bash(curl *)&quot;,</span></span>
<span class="line"><span>      &quot;Edit(.env)&quot;</span></span>
<span class="line"><span>    ]</span></span>
<span class="line"><span>  }</span></span>
<span class="line"><span>}</span></span></code></pre></div><p><strong>规则评估顺序</strong>： <code>deny</code> → <code>ask</code> → <code>allow</code>。deny 规则总是优先。</p><p><strong>Bash 规则通配符</strong>：</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Bash(npm run build)     # 精确匹配 &quot;npm run build&quot;</span></span>
<span class="line"><span>Bash(npm run *)         # 匹配 &quot;npm run&quot; 后跟任意内容</span></span>
<span class="line"><span>Bash(git * main)        # 匹配 &quot;git checkout main&quot;, &quot;git merge main&quot; 等</span></span></code></pre></div><p>注意空格边界： <code>Bash(ls *)</code> 匹配 <code>ls -la</code> 但不匹配 <code>lsof</code>； <code>Bash(ls*)</code> 两者都匹配。</p><p><strong>Read/Edit 规则路径语法</strong>：</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>{</span></span>
<span class="line"><span>  &quot;permissions&quot;: {</span></span>
<span class="line"><span>    &quot;allow&quot;: [</span></span>
<span class="line"><span>      &quot;Read&quot;,</span></span>
<span class="line"><span>      &quot;Edit(/src/**/*.ts)&quot;</span></span>
<span class="line"><span>    ],</span></span>
<span class="line"><span>    &quot;deny&quot;: [</span></span>
<span class="line"><span>      &quot;Read(./.env)&quot;,</span></span>
<span class="line"><span>      &quot;Edit(//etc/passwd)&quot;,</span></span>
<span class="line"><span>      &quot;Read(~/.ssh/*)&quot;</span></span>
<span class="line"><span>    ]</span></span>
<span class="line"><span>  }</span></span>
<span class="line"><span>}</span></span></code></pre></div><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E5%B7%A5%E7%A8%8B%E5%8C%96%E5%AE%9E%E6%88%98/images/957210/92365f94203bd4e8197be5dfb7259a9f.jpg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E5%B7%A5%E7%A8%8B%E5%8C%96%E5%AE%9E%E6%88%98/images/957210/92365f94203bd4e8197be5dfb7259a9f.jpg" alt=""></a></p><p><strong>WebFetch 和 MCP 工具规则</strong>：</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>{</span></span>
<span class="line"><span>  &quot;permissions&quot;: {</span></span>
<span class="line"><span>    &quot;allow&quot;: [</span></span>
<span class="line"><span>      &quot;WebFetch(domain:github.com)&quot;,</span></span>
<span class="line"><span>      &quot;mcp__puppeteer&quot;,</span></span>
<span class="line"><span>      &quot;mcp__database__query&quot;</span></span>
<span class="line"><span>    ],</span></span>
<span class="line"><span>    &quot;deny&quot;: [</span></span>
<span class="line"><span>      &quot;WebFetch(domain:internal.company.com)&quot;,</span></span>
<span class="line"><span>      &quot;mcp__database__drop_table&quot;</span></span>
<span class="line"><span>    ]</span></span>
<span class="line"><span>  }</span></span>
<span class="line"><span>}</span></span></code></pre></div><h3 id="配置文件层级" tabindex="-1">配置文件层级 <a class="header-anchor" href="#配置文件层级" aria-label="Permalink to &quot;配置文件层级&quot;">​</a></h3><p>权限配置可以在多个层级设置，按从高到低的优先级排序，如下表所示。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E5%B7%A5%E7%A8%8B%E5%8C%96%E5%AE%9E%E6%88%98/images/957210/de20da1a7e03238844bcf14fcda058e7.jpg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E5%B7%A5%E7%A8%8B%E5%8C%96%E5%AE%9E%E6%88%98/images/957210/de20da1a7e03238844bcf14fcda058e7.jpg" alt=""></a></p><p>高优先级的配置覆盖低优先级。如果项目配置禁止了某个操作，用户配置无法覆盖。</p><h3 id="cli-工具控制" tabindex="-1">CLI 工具控制 <a class="header-anchor" href="#cli-工具控制" aria-label="Permalink to &quot;CLI 工具控制&quot;">​</a></h3><p>除了配置文件，还可以通过 CLI 参数临时控制工具：</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># 限制可用工具集</span></span>
<span class="line"><span>claude --tools &quot;Read,Grep,Glob&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span># 预授权特定命令（执行时不弹窗）</span></span>
<span class="line"><span>claude --allowedTools &quot;Bash(npm run *)&quot; &quot;Bash(git diff *)&quot; &quot;Read&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span># 禁用特定工具（从上下文中完全移除）</span></span>
<span class="line"><span>claude --disallowedTools &quot;Bash(curl *)&quot; &quot;Edit&quot;</span></span></code></pre></div><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E5%B7%A5%E7%A8%8B%E5%8C%96%E5%AE%9E%E6%88%98/images/957210/44bc61c913e8c3c99d6a48a9ac0f3c52.jpg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E5%B7%A5%E7%A8%8B%E5%8C%96%E5%AE%9E%E6%88%98/images/957210/44bc61c913e8c3c99d6a48a9ac0f3c52.jpg" alt=""></a></p><p>这些控制机制同样适用于子代理配置：</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>---</span></span>
<span class="line"><span>name: code-reviewer</span></span>
<span class="line"><span>description: Review code for security and quality issues</span></span>
<span class="line"><span>tools: Read, Grep, Glob          # 只给只读工具</span></span>
<span class="line"><span>model: sonnet</span></span>
<span class="line"><span>---</span></span></code></pre></div><h2 id="工具扩展与架构定位" tabindex="-1">工具扩展与架构定位 <a class="header-anchor" href="#工具扩展与架构定位" aria-label="Permalink to &quot;工具扩展与架构定位&quot;">​</a></h2><p>下面来看工具扩展的部分。</p><h3 id="工具能力的三个层次" tabindex="-1">工具能力的三个层次 <a class="header-anchor" href="#工具能力的三个层次" aria-label="Permalink to &quot;工具能力的三个层次&quot;">​</a></h3><p>内置工具覆盖了大部分编码任务，但连接外部系统时需要扩展。工具能力可以分为三个层次——从内置原语到 Bash 可达到 MCP 扩展，每一层都在前一层的基础上拓展能力边界。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E5%B7%A5%E7%A8%8B%E5%8C%96%E5%AE%9E%E6%88%98/images/957210/82ce8b4e294c30e1d8d87c8ca17f0efa.jpg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E5%B7%A5%E7%A8%8B%E5%8C%96%E5%AE%9E%E6%88%98/images/957210/82ce8b4e294c30e1d8d87c8ca17f0efa.jpg" alt=""></a></p><p>通过 Bash，Claude 已经可以运行任何命令行工具。那为什么还需要 MCP？三个理由： <strong>结构化输入输出</strong>（MCP 返回结构化数据，不需要解析文本）、 <strong>工具发现</strong>（连接一个 MCP Server，所有工具自动可用）、 <strong>安全隔离</strong>（MCP 在 Server 端做访问控制，比 <code>Bash(curl *)</code> 精细得多）。这些正是上一讲（第 17 讲）详细讲解的内容。</p><h3 id="工具是基础-其他机制是上层建筑" tabindex="-1">工具是基础，其他机制是上层建筑 <a class="header-anchor" href="#工具是基础-其他机制是上层建筑" aria-label="Permalink to &quot;工具是基础，其他机制是上层建筑&quot;">​</a></h3><p>回顾一下 Tools 与其他扩展机制的关系。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E5%B7%A5%E7%A8%8B%E5%8C%96%E5%AE%9E%E6%88%98/images/957210/a951a6a7e21da2ede02d3cbfa91977ed.jpg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E5%B7%A5%E7%A8%8B%E5%8C%96%E5%AE%9E%E6%88%98/images/957210/a951a6a7e21da2ede02d3cbfa91977ed.jpg" alt=""></a></p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E5%B7%A5%E7%A8%8B%E5%8C%96%E5%AE%9E%E6%88%98/images/957210/b96f4124fa221d40aa518a0e4fe770a9.jpg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E5%B7%A5%E7%A8%8B%E5%8C%96%E5%AE%9E%E6%88%98/images/957210/b96f4124fa221d40aa518a0e4fe770a9.jpg" alt=""></a></p><p>这种分层设计让你可以在不同粒度上精确控制 Claude 的能力边界。所有你在前面学过的扩展机制 SubAgents、Skills、Commands、Hooks、MCP，都建立在 Tools 基础上。理解了工具系统，就理解了整座大厦的地基。</p><h2 id="总结一下" tabindex="-1">总结一下 <a class="header-anchor" href="#总结一下" aria-label="Permalink to &quot;总结一下&quot;">​</a></h2><p>这一讲我们像庖丁解牛般，把 Claude Code 的工具系统彻底拆开来看了看。</p><p><strong>Agentic Loop</strong> 是 Claude Code 的工作核心：收集上下文 → 采取行动 → 验证结果，循环往复。工具是行动的载体，没有工具的 Claude 只能输出文本。Claude Code 作为 Agentic Harness，把模型和工具连接起来。</p><p><strong>工具设计哲学</strong> 遵循 Unix 原则——十几个精选的原语工具覆盖了五个原子操作：感知（Read）、搜索（Glob/Grep）、修改（Edit/Write）、执行（Bash）、获取（Web）。涌现公式：原语工具 × LLM 推理 × 反馈循环 = 无限复杂能力。重构、调试、部署这些高级能力不需要专门的工具，它们是原语工具在 LLM 推理驱动下的涌现行为。</p><p><strong>权限控制</strong> 分层相当精细。权限模式从 default 到 bypassPermissions 六档可调；规则语法支持通配符、路径模式、域名限制；配置层级从 Managed（组织级）到 User（个人级）四层叠加。</p><p><strong>工具扩展</strong> 分三个层次：内置原语 → Bash 可达 → MCP 扩展。Tools 是基础层，Sub-Agents、Skills、Hooks、MCP这些上层建筑， 都建立在 Tools 层之上。</p><h2 id="思考题" tabindex="-1">思考题 <a class="header-anchor" href="#思考题" aria-label="Permalink to &quot;思考题&quot;">​</a></h2><p>1.如果你要设计一个“只能读代码、不能修改任何东西”的子代理，应该给它配置哪些工具？</p><p>2.我们说“重构”不是一个工具，而是多个原语工具在 LLM 推理驱动下的涌现行为。请选择你工作中的一项复杂任务（如“数据库迁移”、“API 版本升级”），分解它由哪些原子操作组成。</p><p>3.为什么 Bash 命令的“不再询问”授权是永久的，而文件编辑的授权只在会话内有效？这种设计背后的安全考量是什么？</p><p>4.如果你担心 Claude 通过 Bash 执行 <code>curl</code> 访问不该访问的 URL，有哪些防护手段？</p><p>5.课程里提到 Claude Code 选择了“~15 个原语工具”这个平衡点。如果让你为某个特定领域（比如数据科学、运维、前端开发）设计一个 AI Agent 的工具集，你会选择哪些原语？为什么？</p><h2 id="下一讲预告" tabindex="-1">下一讲预告 <a class="header-anchor" href="#下一讲预告" aria-label="Permalink to &quot;下一讲预告&quot;">​</a></h2><p>工具系统定义了 Claude Code <strong>能做什么</strong>，但到目前为止，我们一直有一个前提：你得坐在终端前面，实时和 Claude 对话。如果 Claude 能在没有人的情况下自动工作呢？</p><p>下一讲，我们将学习 <strong>Headless 模式与 CI/CD 集成</strong>——让 Claude Code 在无人值守的情况下静默运行。你将学会如何在 GitHub Actions 中配置 Claude Code、如何用 Headless 模式实现自动化代码审查，以及如何将 Claude Code 嵌入持续集成流水线，让它成为团队 DevOps 工作流的一部分。</p><p>欢迎你在留言区参与讨论，如果这节课对你有启发，别忘了分享给身边更多朋友。</p>`,132)])])}const h=a(i,[["render",p]]);export{g as __pageData,h as default};
